Let's build the blue cell set and a (row, col) mapping for fast checks.

```python
# python
from openpyxl.utils import column_index_from_string

def is_blue(hex_color):
    if not hex_color:
        return False
    r = int(hex_color[0:2], 16)
    g = int(hex_color[2:4], 16)
    b = int(hex_color[4:6], 16)
    return b > 200 and r < 60 and g < 190

# Convert Excel coord (e.g., A1) to (row, col)
def coord_to_indices(coord):
    i = 0
    while i < len(coord) and coord[i].isalpha():
        i += 1
    col = column_index_from_string(coord[:i])
    row = int(coord[i:])
    return (row, col)

blue_indices = set()
cell_map = {}
for coord, info in map_data.items():
    rc = coord_to_indices(coord)
    cell_map[rc] = {'value': info['value'], 'color': info['color']}
    if is_blue(info['color']):
        blue_indices.add(rc)

print("Blue cells count:", len(blue_indices))
print("First few blue indices:", list(blue_indices)[:5])
```
